processor-info.script:

 String cmd = input.getText("cmd");  

	//회원사 조회 이면 
 if( "select_mbmaster_list".equals(cmd) ) 
 {

     StringBuffer addWhere = new StringBuffer();

     //지회코드  
     String search_gbn_jicode = input.getText("search_gbn_jicode") ;

     if ( search_gbn_jicode !=null && !search_gbn_jicode.equals("%") )
     {
         addWhere.append(" and ji_code = '" + search_gbn_jicode + "' ");
     }


     //검색 옵션 
     String search_value = input.getText("search_value") ;

     //공백이면 비교할 필요가 없다 (All 검색)
     if ( search_value !=null && !search_value.equals("") )
     {

         String search_gbn_option = input.getText("search_gbn_option") ;



         //상호명 
         if(search_gbn_option.equals("company")){
             addWhere.append(" and company like '%" + search_value + "%' ");
         }

         //대표자 
         if(search_gbn_option.equals("rprstt_kr")){
             addWhere.append(" and rprstt_kr like '%" + search_value + "%' ");
         }

         //주소 
         if(search_gbn_option.equals("add")){
             addWhere.append(" and (CP_ADDR like '%" + search_value + "%'  or CP_JIBUN like '%"  + search_value + "%'    ) ");
         }

         //전화번호 
         if(search_gbn_option.equals("cptel")){
             addWhere.append(" and cptel like '%" + search_value + "%' ");  
         }

         //팩스
         if(search_gbn_option.equals("cdfax")){
             addWhere.append(" and cdfax like '%" + search_value + "%' ");
         }
     }


     input.put("addWhere", addWhere.toString() );

 	executeSQL(cmd, connection, input, output);
 }else{
 	executeSQL(cmd, connection, input, output);
 }
